import{_ as r,o as e,c as a,ag as d}from"./chunks/framework.BjY7aUvS.js";const b=JSON.parse('{"title":"考证防坑 · 证书真伪与国家目录核对","description":"考出来的证是真的吗：人社部技能人才评价证书全国联网查询 + 国家职业资格目录核对 + 中国人事考试网，识别目录外野鸡证与\\"包过挂靠\\"骗局。","frontmatter":{"title":"考证防坑 · 证书真伪与国家目录核对","issuer":"人力资源和社会保障部","source_tier":"一级来源","version":"—","published":"—","source_url":"http://zscx.osta.org.cn/","status":"现行服务","tags":["官方查询","考证","职业资格","防坑","证书"],"type":"查询页","reviewed":false,"description":"考出来的证是真的吗：人社部技能人才评价证书全国联网查询 + 国家职业资格目录核对 + 中国人事考试网，识别目录外野鸡证与\\"包过挂靠\\"骗局。"},"headers":[],"relativePath":"query/cert-search.md","filePath":"query/cert-search.md"}'),o={name:"query/cert-search.md"};function n(h,t,s,l,c,i){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="考证防坑-·-证书真伪与国家目录核对" tabindex="-1">考证防坑 · 证书真伪与国家目录核对 <a class="header-anchor" href="#考证防坑-·-证书真伪与国家目录核对" aria-label="Permalink to &quot;考证防坑 · 证书真伪与国家目录核对&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 会话信息整理并经浏览器核验入口可达；具体目录项数与细则以人社部最新文件为准。</p></div><blockquote><p><strong>官方入口</strong>：人社部<a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">技能人才评价证书全国联网查询</a>（职业技能等级证/职业资格证）；<a href="http://www.cpta.com.cn/" target="_blank" rel="noreferrer">中国人事考试网</a>（专业技术人员资格考试报名/成绩/证书）。· 一级来源（<a href="http://www.cpta.com.cn/" target="_blank" rel="noreferrer">两入口已核验可达</a>）</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>判断一张证有没有用，<strong>第一步不是查真伪，是查它在不在《国家职业资格目录》里</strong>——目录内的才叫国家职业资格（准入类上岗必须持证；水平类分等级证明能力）；<strong>目录外的证书，再唬人的名字也只是培训机构发的结业证明</strong>。技能人员水平评价类资格已退出目录，转为<strong>职业技能等级认定</strong>（证书同样可在官方联网系统查）。</p><h2 id="_30-秒核验步骤-待核验" tabindex="-1">30 秒核验步骤（待核验） <a class="header-anchor" href="#_30-秒核验步骤-待核验" aria-label="Permalink to &quot;30 秒核验步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>先查目录：这份证属于哪一类？在不在《国家职业资格目录（2021 年版）》（人社部官网可查，<strong>待核验</strong>）？</td></tr><tr><td>2</td><td>查真伪：职业技能等级证/职业资格证 → <a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">技能人才评价证书全国联网查询</a>，输入姓名+证书编号</td></tr><tr><td>3</td><td>专技类（一建、注会、教师等）→ <a href="http://www.cpta.com.cn/" target="_blank" rel="noreferrer">中国人事考试网</a> 查成绩与证书</td></tr><tr><td>4</td><td>三步都对上，证才是&quot;国家承认&quot;</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>联网系统查到、信息一致</td><td>官方认可证书（<a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">查询系统</a>）</td></tr><tr><td>查无此证</td><td>假证或野鸡证——培训机构发的&quot;国际注册××师&quot;多数查不到</td></tr><tr><td>目录外的证</td><td>不是假证但<strong>不是国家职业资格</strong>，不能作为持证上岗依据</td></tr></tbody></table><h2 id="常见证书归类示例-家庭速查" tabindex="-1">常见证书归类示例（家庭速查） <a class="header-anchor" href="#常见证书归类示例-家庭速查" aria-label="Permalink to &quot;常见证书归类示例（家庭速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>例子</th><th>含金量来源</th></tr></thead><tbody><tr><td><strong>准入类</strong>职业资格</td><td>法律职业资格、教师资格、执业医师、注册会计师、一级建造师</td><td>上岗必须持证（目录内，待核验）</td></tr><tr><td><strong>水平评价类</strong>职业资格</td><td>经济师、翻译资格等</td><td>目录内，分等级证明能力</td></tr><tr><td><strong>职业技能等级证书</strong></td><td>健康管理师、公共营养师、电工等（原目录内技能资格转出）</td><td>由备案评价机构认定，<a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">联网可查</a></td></tr><tr><td><strong>从来不是国家资格</strong></td><td>&quot;国际注册××师&quot;&quot;协会认证××师&quot;等</td><td>培训结业证明，无持证上岗效力</td></tr></tbody></table><p>考出<strong>目录内证书或技能等级证书</strong>还可能领政府补贴：<a href="/SageRelay/query/skill-subsidy.html">技能提升补贴申领</a>。</p><h2 id="避坑要点-考证重灾区" tabindex="-1">避坑要点（考证重灾区） <a class="header-anchor" href="#避坑要点-考证重灾区" aria-label="Permalink to &quot;避坑要点（考证重灾区）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方事实</th></tr></thead><tbody><tr><td>&quot;健康管理师国家资格证，考完挂靠月入过万&quot;</td><td>健康管理师 2020 年已退出国家职业资格目录，现为<strong>职业技能等级认定</strong>；&quot;挂靠躺赚&quot;为虚假宣传（待核验）</td></tr><tr><td>&quot;包过、不用考试直接拿证&quot;</td><td>国家级考试无包过；免考拿证多为假证或培训结业证冒充</td></tr><tr><td>&quot;国际认证，全球通用，比国内证高级&quot;</td><td>境外证书不在国家职业资格目录内，境内执业以目录为准</td></tr><tr><td>【本站提示】报名前先花 30 秒查目录+查发证机构备案，再交钱</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>学历文凭：<a href="/SageRelay/query/education-verify.html">学历学籍查询（学信网）</a></li><li>商家底细：<a href="/SageRelay/query/enterprise-credit.html">企业信用查询</a>（培训机构也可查处罚记录）</li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>人社部技能人才评价证书全国联网查询、中国人事考试网（一级来源）</td></tr><tr><td>入口</td><td><a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">zscx.osta.org.cn</a> · <a href="http://www.cpta.com.cn/" target="_blank" rel="noreferrer">cpta.com.cn</a>（均已核验可达；热线 12333）</td></tr></tbody></table>',18)])])}const g=r(o,[["render",n]]);export{b as __pageData,g as default};
